from decimal import Decimal


def stacked(price, discounts):
    for d in discounts:
        price = price * (1 - d)
    return price


def additive(price, discounts):
    return price * (1 - sum(discounts))


p = Decimal("100")
ds = [Decimal("0.10"), Decimal("0.20")]
print(f"stacked(p, ds) -> {stacked(p, ds)}")
print(f"additive(p, ds) -> {additive(p, ds)}")
print(f"stacked(p, ds[::-1]) -> {stacked(p, ds[::-1])}")
print(f"additive(p, [Decimal('0.6'), Decimal('0.5')]) -> {additive(p, [Decimal('0.6'), Decimal('0.5')])}")

