def show(label, fn):
    try:
        r = fn()
    except Exception as e:
        r = type(e).__name__
    print(f"{label} -> {r!r}")



def parse_rule(rule):
    match rule.split(":"):
        case ["pct", value]:
            return ("pct", float(value))
        case ["fixed", value]:
            return ("fixed", int(value))
        case _:
            return ("unknown", rule)


for r in ["pct:10", "fixed:250", "PCT:10", "pct:10:extra", "fixed:2.5"]:
    show(f"parse_rule({r!r})", lambda: parse_rule(r))

